/**
 * P-05 Agent Panel (JARVIS), with P-05b turn-limit banner and P-05c
 * model-not-configured state. P-05a tool cards live in components/ToolCard.
 *
 * Assistant text is untrusted: it renders as escaped text with a visible
 * "AI-generated" label. Tool cards are generated by the backend from the
 * ToolCallRecord, never parsed out of model text, so an injection cannot forge
 * one (design T-10).
 */

import { useEffect, useMemo, useRef, useState } from 'react';
import type { AgentRequestState } from '../../contracts';
import { useAppActions, useAppState } from '../store';
import { TranscriptView } from './TranscriptView';

const BUSY_STATES = new Set<AgentRequestState>(['thinking', 'awaiting-tool', 'answering', 'stopping']);

export function AgentPanel(): JSX.Element {
  const state = useAppState();
  const actions = useAppActions();
  const [draft, setDraft] = useState('');
  const [outcomeFilter, setOutcomeFilter] = useState<'all' | 'ok' | 'refused'>('all');
  const [delegationGoal, setDelegationGoal] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);

  const agent = state.agent;
  const isBusy = agent ? BUSY_STATES.has(agent.request.state) : false;
  const modelMissing = !state.settings || state.settings.modelState !== 'configured';

  const entries = useMemo(() => {
    if (!agent) return [];
    if (outcomeFilter === 'all') return agent.transcript;
    return agent.transcript.filter((entry) =>
      entry.toolCallIds.some((id) => {
        const record = agent.toolCallsById[id];
        if (!record) return false;
        return outcomeFilter === 'ok' ? record.outcome === 'ok' : record.outcome !== 'ok';
      }),
    );
  }, [agent, outcomeFilter]);

  useEffect(() => {
    const el = scrollRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [entries.length, agent?.request.state]);

  const onSend = (): void => {
    const text = draft.trim();
    if (text.length === 0 || isBusy) return;
    setDraft('');
    void actions.sendAgent(text);
  };

  const maxChars = agent?.input.maxChars ?? 4000;

  return (
    <aside className="dock dock-right agent-panel">
      <header className="dock-head">
        <span className="jarvis-title">JARVIS</span>
        {agent ? <span className={`badge badge-${isBusy ? 'busy' : 'idle'}`}>{agent.request.state}</span> : null}
        <span className="dock-head-spacer" />
        <button type="button" className="icon-btn" title="Conversation history" onClick={() => actions.setOverlay('history')}>
          &#9776;
        </button>
        <button type="button" className="icon-btn" title="Clear conversation" onClick={() => void actions.clearAgent()}>
          &#9003;
        </button>
      </header>

      {agent && agent.request.turnCap > 0 ? (
        <div className="turn-meter" title="Agent turn budget">
          <span className="muted small">
            turn {agent.request.turnCount}/{agent.request.turnCap}
          </span>
          <div className="meter-track">
            <div
              className="meter-fill"
              style={{ width: `${Math.min(100, (agent.request.turnCount / agent.request.turnCap) * 100)}%` }}
            />
          </div>
          <span className="muted small">{agent.requestCapRemaining} req left</span>
        </div>
      ) : null}

      {agent?.request.state === 'turn-limit' ? (
        <div className="banner banner-warn">
          Turn limit reached ({agent.request.turnCount}/{agent.request.turnCap}). The request stopped
          cleanly; send a follow-up to continue.
        </div>
      ) : null}

      {modelMissing ? (
        <div className="empty-state inline">
          <h3>Model not configured</h3>
          <p className="muted">JARVIS needs an API key before it can answer.</p>
          <button type="button" className="btn btn-primary" onClick={() => actions.setOverlay('settings')}>
            Open settings
          </button>
        </div>
      ) : null}

      <div className="transcript-toolbar">
        {(['all', 'ok', 'refused'] as const).map((filter) => (
          <button
            key={filter}
            type="button"
            className={`chip chip-btn ${outcomeFilter === filter ? 'chip-active' : ''}`}
            onClick={() => setOutcomeFilter(filter)}
          >
            {filter}
          </button>
        ))}
      </div>

      <div className="transcript" ref={scrollRef}>
        <TranscriptView entries={entries} toolCalls={agent?.toolCallsById ?? {}} />
      </div>

      <div className="composer">
        <textarea
          className="composer-input"
          value={draft}
          maxLength={maxChars}
          placeholder={modelMissing ? 'Configure a model to chat' : 'Ask JARVIS...'}
          onChange={(e) => setDraft(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
              e.preventDefault();
              onSend();
            }
          }}
          disabled={modelMissing}
          aria-label="Message JARVIS"
        />
        <div className="composer-bar">
          <span className="muted small">
            {draft.length}/{maxChars}
          </span>
          {isBusy ? (
            <button type="button" className="btn btn-danger" onClick={() => void actions.stopAgent()}>
              Stop
            </button>
          ) : (
            <button type="button" className="btn btn-primary" onClick={onSend} disabled={draft.trim().length === 0 || modelMissing}>
              Send
            </button>
          )}
        </div>
      </div>

      <div className="delegation-launcher">
        <span className="muted small">Delegation (requires approval)</span>
        <div className="delegation-row">
          <input
            className="delegation-goal"
            value={delegationGoal}
            placeholder="Goal for the external agent CLI"
            onChange={(e) => setDelegationGoal(e.target.value)}
            aria-label="Delegation goal"
          />
          <button
            type="button"
            className="btn btn-ghost"
            disabled={delegationGoal.trim().length === 0 || state.delegation?.state === 'running'}
            onClick={() => {
              void actions.launchDelegation(delegationGoal.trim());
              setDelegationGoal('');
            }}
          >
            Launch
          </button>
        </div>
      </div>
    </aside>
  );
}
